// Classify every unpaid invoice into an escalation tier and draft the email.
// Edit the three email templates below to match your voice.

const REMIND_EVERY_DAYS = 7; // never email the same client more often than this
const today = new Date();
today.setHours(0, 0, 0, 0);

const out = [];

for (const item of $input.all()) {
  const inv = item.json;

  if (String(inv.Status || '').trim().toLowerCase() !== 'unpaid') continue;
  if (!inv.DueDate || !inv.ClientEmail) continue;

  const due = new Date(inv.DueDate);
  if (isNaN(due)) continue;
  due.setHours(0, 0, 0, 0);

  const daysOverdue = Math.floor((today - due) / 86400000);
  if (daysOverdue < 3) continue; // small grace period

  // throttle: skip if a reminder went out recently
  if (inv.LastReminderDate) {
    const last = new Date(inv.LastReminderDate);
    if (!isNaN(last) && (today - last) / 86400000 < REMIND_EVERY_DAYS) continue;
  }

  const tier = daysOverdue >= 30 ? 3 : daysOverdue >= 14 ? 2 : 1;
  const amount = `${inv.Amount} ${inv.Currency || ''}`.trim();
  const firstName = String(inv.ClientName || 'there').split(' ')[0];

  let subject, body;

  if (tier === 1) {
    subject = `Friendly reminder: invoice ${inv.InvoiceNumber} (${amount})`;
    body = `Hi ${firstName},\n\nJust a quick note that invoice ${inv.InvoiceNumber} for ${amount} was due on ${inv.DueDate} and looks unpaid on our side.\n\nIf you've already sent the payment — thank you, please ignore this. Otherwise it would be great if you could settle it this week.\n\nIf anything is unclear about the invoice, just reply to this email.\n\nBest regards`;
  } else if (tier === 2) {
    subject = `Second reminder: invoice ${inv.InvoiceNumber} is ${daysOverdue} days overdue`;
    body = `Hi ${firstName},\n\nInvoice ${inv.InvoiceNumber} for ${amount} is now ${daysOverdue} days past its due date (${inv.DueDate}).\n\nPlease arrange payment within the next 5 business days, or let me know when we can expect it.\n\nIf there is an issue with the invoice or the work, reply here and we'll sort it out quickly.\n\nBest regards`;
  } else {
    subject = `FINAL NOTICE: invoice ${inv.InvoiceNumber} — ${daysOverdue} days overdue`;
    body = `Hi ${firstName},\n\nDespite previous reminders, invoice ${inv.InvoiceNumber} for ${amount} remains unpaid ${daysOverdue} days after its due date (${inv.DueDate}).\n\nPlease settle the amount within 7 days. After that we will have to pause ongoing work and may add late-payment charges as per our terms.\n\nI would much rather resolve this simply — if payment is already on its way, a quick reply is enough.\n\nRegards`;
  }

  out.push({
    json: {
      row_number: inv.row_number,
      InvoiceNumber: inv.InvoiceNumber,
      ClientName: inv.ClientName,
      ClientEmail: inv.ClientEmail,
      Amount: inv.Amount,
      Currency: inv.Currency || '',
      DueDate: inv.DueDate,
      daysOverdue,
      tier,
      subject,
      body,
      remindersSent: (parseInt(inv.RemindersSent, 10) || 0) + 1,
      todayISO: today.toISOString().slice(0, 10),
    },
  });
}

return out;
